import{_ as e,o as i,c as l,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"Summary","description":"","frontmatter":{},"headers":[],"relativePath":"SUMMARY.md","filePath":"SUMMARY.md","lastUpdated":1788475713000}'),t={name:"SUMMARY.md"};function o(s,a,h,n,u,c){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h1><p><a href="./">前言</a></p><hr><h1 id="导论卷-·-计算机基础知识体系" tabindex="-1">导论卷 · 计算机基础知识体系 <a class="header-anchor" href="#导论卷-·-计算机基础知识体系" aria-label="Permalink to &quot;导论卷 · 计算机基础知识体系&quot;">​</a></h1><blockquote><p>沿时间轴 (1936 → 2026) 与抽象层级 (晶体管 → AI 模型) 把全书 13 主题串起来的纵贯线, 让读者先在脑子里搭起一座&quot;全景骨架&quot;, 再下钻各主题时不再&quot;信息孤岛&quot;.</p></blockquote><ul><li><a href="./prologue/">开篇: 这卷要做什么</a><ul><li><a href="./prologue/history">1. 计算机发展史纵贯线: 1936 → 2026</a></li><li><a href="./prologue/abstraction-layers">2. 抽象层级: 从晶体管到 AI 模型的十层金字塔</a></li><li><a href="./prologue/mainframe-xpu">3. 形态演进: 大型机 → PC → 单片机/ARM → 云 → Web → AI → XPU</a></li><li><a href="./prologue/standing-on-shoulders">4. 主干纵贯: CPU/内存 → OS/Linux → 网络/Web → DB → 编译 → 分布式 → AI 的承接链</a></li><li><a href="./prologue/map">5. 全书地图: 13 部分与导论的交叉索引</a></li></ul></li></ul><hr><h1 id="学习笔记-·-心得记录" tabindex="-1">学习笔记 · 心得记录 <a class="header-anchor" href="#学习笔记-·-心得记录" aria-label="Permalink to &quot;学习笔记 · 心得记录&quot;">​</a></h1><blockquote><p>随读随记的轻量工具：笔记默认只存在你的浏览器 localStorage（不注册、无数据库），需要沉淀时一键导出为 GitHub Issue，或复制 Markdown 粘贴到 Discussions / 自己的仓库。</p></blockquote><ul><li><a href="./notes/">开篇: 个人笔记工具与用法</a></li><li><a href="./notes/journal">心得日志: 把想法沉淀成条目</a></li></ul><hr><h1 id="第零部分-·-工程数学与离散数学基础" tabindex="-1">第零部分 · 工程数学与离散数学基础 <a class="header-anchor" href="#第零部分-·-工程数学与离散数学基础" aria-label="Permalink to &quot;第零部分 · 工程数学与离散数学基础&quot;">​</a></h1><blockquote><p>把后面十三部分反复出现的同一组数学抽到一处讲透: 离散结构 + 线性代数 + 概率统计 + 微积分/优化. 让后续读 DSA / OS / DB / Compiler / Crypto / 信息论 / Transformer 时, 数学不再是被卡的那一关.</p></blockquote><ul><li><a href="./math/">开篇: 工程数学 + 离散数学为什么放最前</a><ul><li><a href="./math/discrete">1. 离散数学: 逻辑 / 集合 / 关系 / 图 / 组合 / 递推 / 代数结构</a></li><li><a href="./math/linalg">2. 线性代数: 向量空间 / 矩阵 / 谱 / SVD / 张量</a></li><li><a href="./math/prob">3. 概率统计: 分布 / 贝叶斯 / MLE / MAP / 极限 / KL</a></li><li><a href="./math/calc-opt">4. 微积分与最优化: 链式法则 / 雅可比 / Hessian / 凸优化 / 信息几何</a></li></ul></li></ul><hr><h1 id="工程化实践轴-·-让代码真正跑进生产" tabindex="-1">工程化实践轴 · 让代码真正跑进生产 <a class="header-anchor" href="#工程化实践轴-·-让代码真正跑进生产" aria-label="Permalink to &quot;工程化实践轴 · 让代码真正跑进生产&quot;">​</a></h1><blockquote><p>与 14 部分&quot;计算机原理&quot;互补的手艺轴：Git 版本控制 / 测试工程 / CI-CD 发布 / 性能工程 / 应用安全 / 代码质量 / 可观测性。定位是&quot;1-20 年工程师把基础落地到生产&quot;。</p></blockquote><ul><li><a href="./engineering/">开篇: 工程化 = 让代码跑进生产的手艺</a><ul><li><a href="./engineering/git-workflow">1. Git 与版本控制: 原理 / 分支模型 / 合并策略 / 进阶命令</a></li><li><a href="./engineering/testing">2. 测试工程: 测试金字塔 / 单元/集成/契约/E2E / mock / flaky 治理</a></li><li><a href="./engineering/cicd-devops">3. CI/CD 与发布工程: 管线 / 镜像 / 蓝绿金丝雀 / IaC</a></li><li><a href="./engineering/performance-engineering">4. 性能工程: profiling / 火焰图 / 缓存与批处理方法论</a></li><li><a href="./engineering/app-security">5. 应用安全: OWASP Top 10 / 认证授权 / 数据安全 / 供应链</a></li><li><a href="./engineering/code-quality">6. 代码质量: 重构 / code review / 复杂度治理 / DDD 落地</a></li><li><a href="./engineering/observability-practice">7. 可观测性实操: metrics/logs/traces 打点 / OpenTelemetry / SLO</a></li><li><a href="./engineering/gh-actions-deepdive">8. GitHub Actions 实战: workflow / expression / 缓存 / 矩阵 / reusable / 自托管</a></li><li><a href="./engineering/gitops-k8s">9. 云原生发布与 GitOps: K8s 应用 / Helm / ArgoCD / Flux / 服务网格</a></li><li><a href="./engineering/sre-engineering">10. SRE 工程: 错误预算 / 容量 / 变更 / 事件响应 / 生产就绪</a></li></ul></li></ul><hr><h1 id="第一部分-·-数据结构与算法-dsa" tabindex="-1">第一部分 · 数据结构与算法（DSA） <a class="header-anchor" href="#第一部分-·-数据结构与算法-dsa" aria-label="Permalink to &quot;第一部分 · 数据结构与算法（DSA）&quot;">​</a></h1><ul><li><a href="./dsa/">开篇：为什么从头学 DSA</a></li><li><a href="./dsa/algorithms/complexity">复杂度分析</a><ul><li><a href="./dsa/algorithms/complexity/notation">渐进记号的真实含义</a></li><li><a href="./dsa/algorithms/complexity/amortized">摊还分析入门</a></li><li><a href="./dsa/algorithms/complexity/practice">实战：复杂度反推设计</a></li></ul></li><li><a href="./dsa/structures/">基本数据结构</a><ul><li><a href="./dsa/structures/array">数组与动态数组</a></li><li><a href="./dsa/structures/linked-list">链表：单链/双链/跳表</a></li><li><a href="./dsa/structures/stack-queue">栈与队列</a></li><li><a href="./dsa/structures/hash-table">哈希表：从原理到工程</a></li></ul></li><li><a href="./dsa/structures/trees/">树结构</a><ul><li><a href="./dsa/structures/trees/bst">二叉搜索树与平衡</a></li><li><a href="./dsa/structures/trees/avl-rbt">AVL 与红黑树</a></li><li><a href="./dsa/structures/trees/btree">B 树与 B+ 树</a></li><li><a href="./dsa/structures/trees/heap">堆与优先队列</a></li><li><a href="./dsa/structures/trees/trie-union">字典树与并查集</a></li></ul></li><li><a href="./dsa/structures/graphs/">图</a><ul><li><a href="./dsa/structures/graphs/representation">图的表示与遍历</a></li><li><a href="./dsa/structures/graphs/shortest-path">最短路径：Dijkstra / Bellman-Ford / Floyd</a></li><li><a href="./dsa/structures/graphs/mst">最小生成树：Kruskal / Prim</a></li><li><a href="./dsa/structures/graphs/topo-scc">拓扑排序与强连通分量</a></li><li><a href="./dsa/structures/graphs/flow">网络流入门</a></li></ul></li><li><a href="./dsa/algorithms/">算法设计范式</a><ul><li><a href="./dsa/algorithms/divide-conquer">分治</a></li><li><a href="./dsa/algorithms/greedy">贪心</a></li><li><a href="./dsa/algorithms/dp">动态规划</a></li><li><a href="./dsa/algorithms/backtracking">回溯与剪枝</a></li><li><a href="./dsa/algorithms/branch-bound">分支限界</a></li></ul></li><li><a href="./dsa/topics/">经典算法专题</a><ul><li><a href="./dsa/topics/sorting">排序：从朴素到极致</a></li><li><a href="./dsa/topics/searching">搜索：二分与三分</a></li><li><a href="./dsa/topics/string">字符串：KMP / Z / Rabin-Karp / AC 自动机</a></li><li><a href="./dsa/topics/number-theory">数论与模运算</a></li></ul></li><li><a href="./dsa/appendix/">附录</a><ul><li><a href="./dsa/appendix/snippets">Snippets</a></li><li><a href="./dsa/appendix/leetcode-roadmap">LeetCode 刷题路线</a></li></ul></li></ul><hr><h1 id="第二部分-·-操作系统" tabindex="-1">第二部分 · 操作系统 <a class="header-anchor" href="#第二部分-·-操作系统" aria-label="Permalink to &quot;第二部分 · 操作系统&quot;">​</a></h1><ul><li><a href="./os/">开篇：操作系统到底在帮你做什么</a></li><li><a href="./os/memory/">内存</a><ul><li><a href="./os/memory/virtual-memory">虚拟内存与地址翻译</a></li><li><a href="./os/memory/tlb-hugepage">分页、TLB、Huge Page</a></li><li><a href="./os/memory/replacement">页面置换与 working set</a></li><li><a href="./os/memory/allocator">内存分配器：ptmalloc/jemalloc/tcmalloc/mimalloc</a></li><li><a href="./os/memory/numa">NUMA 与 CXL 内存池</a></li></ul></li><li><a href="./os/fs/">文件系统</a><ul><li><a href="./os/fs/inode-pagecache">inode、dentry、page cache</a></li><li><a href="./os/fs/filesystems">ext4 / XFS / Btrfs 设计差异</a></li><li><a href="./os/fs/io-modes">Direct IO、mmap、io_uring</a></li><li><a href="./os/fs/crash-consistency">WAL、fsync、崩溃一致性</a></li></ul></li><li><a href="./os/sched/">进程与线程调度</a><ul><li><a href="./os/sched/cfs">Linux CFS 调度器</a></li><li><a href="./os/sched/rt">实时调度：SCHED_FIFO / RR / EDF</a></li><li><a href="./os/sched/gmp">goroutine GMP 模型</a></li><li><a href="./os/sched/cgroup">Cgroup v2、CPU 迁移与亲和</a></li></ul></li><li><a href="./os/lock/">锁与同步原语</a><ul><li><a href="./os/lock/futex-cas">futex、CAS、spinlock 内部</a></li><li><a href="./os/lock/rcu">RCU、seqlock、brlock</a></li><li><a href="./os/lock/memory-barrier">内存模型与 memory barrier</a></li><li><a href="./os/lock/lockfree">lock-free/wait-free 数据结构</a></li></ul></li><li><a href="./os/virtualization">虚拟化与容器: VM / KVM / namespaces / gVisor</a></li><li><a href="./os/net/">IO 与网络栈</a><ul><li><a href="./os/net/epoll-iouring">epoll / kqueue / io_uring 对比</a></li><li><a href="./os/net/zero-copy">Zero copy：sendfile / splice / MSG_ZEROCOPY</a></li><li><a href="./os/net/kernel-tcp">TCP/IP 内核栈与 NAPI</a></li><li><a href="./os/net/xdp-dpdk">XDP、DPDK 与 kernel bypass</a></li></ul></li></ul><hr><h1 id="第三部分-·-计算机网络" tabindex="-1">第三部分 · 计算机网络 <a class="header-anchor" href="#第三部分-·-计算机网络" aria-label="Permalink to &quot;第三部分 · 计算机网络&quot;">​</a></h1><ul><li><a href="./networking/">开篇：为什么协议要分层</a></li><li><a href="./networking/phy/">物理层 / 数据链路层</a><ul><li><a href="./networking/phy/ethernet">以太网帧、CSMA/CD、PHY/MAC</a></li><li><a href="./networking/phy/optical">光纤、波分复用、机房布线</a></li></ul></li><li><a href="./networking/ip/">IP / 路由</a><ul><li><a href="./networking/ip/ipv6">IPv4 / IPv6 / ICMP</a></li><li><a href="./networking/ip/arp-dhcp">DHCP / ARP / NDP</a></li><li><a href="./networking/ip/bgp-ospf">BGP / OSPF 路由</a></li><li><a href="./networking/ip/nat">NAT 与 conntrack</a></li><li><a href="./networking/ip/dns">DNS: 名字解析 / 缓存 / CDN 调度 / DNSSEC</a></li></ul></li><li><a href="./networking/tcp/">TCP/UDP</a><ul><li><a href="./networking/tcp/handshake">三次握手 / 四次挥手 / TIME_WAIT</a></li><li><a href="./networking/tcp/congestion">拥塞控制：Reno / Cubic / BBR</a></li><li><a href="./networking/tcp/retransmission">重传、SACK、RTO/RTT 估计</a></li></ul></li><li><a href="./networking/http/">HTTP / TLS</a><ul><li><a href="./networking/http/versions">HTTP 1.0 → 1.1 → 2 → 3</a></li><li><a href="./networking/http/tls">HTTPS / TLS 1.3 握手与 0-RTT</a></li><li><a href="./networking/http/pki">证书链 / PKI / OCSP stapling</a></li><li><a href="./networking/http/rpc">gRPC / Protobuf / Thrift</a></li></ul></li><li><a href="./networking/quic/">QUIC</a><ul><li><a href="./networking/quic/overview">QUIC over UDP：解决什么</a></li><li><a href="./networking/quic/0rtt">0-RTT / 连接迁移</a></li><li><a href="./networking/quic/bbr">BBR 在 QUIC 下的表现</a></li></ul></li></ul><hr><h1 id="第四部分-·-数据库系统" tabindex="-1">第四部分 · 数据库系统 <a class="header-anchor" href="#第四部分-·-数据库系统" aria-label="Permalink to &quot;第四部分 · 数据库系统&quot;">​</a></h1><ul><li><a href="./databases/">开篇：数据库在解决什么</a></li><li><a href="./databases/relational/">SQL 与关系模型</a><ul><li><a href="./databases/relational/relational">关系代数、SQL semantics</a></li><li><a href="./databases/relational/isolation">事务、ACID、隔离级别与现象</a></li><li><a href="./databases/relational/mvcc">MVCC 原理：PostgreSQL vs InnoDB</a></li><li><a href="./databases/relational/wal-2pl">WAL / redo / undo / 2PL</a></li></ul></li><li><a href="./databases/indexing/">索引与存储结构</a><ul><li><a href="./databases/indexing/btree">B+ 树索引与覆盖索引</a></li><li><a href="./databases/indexing/lsm">LSM-Tree 与 SSTable</a></li><li><a href="./databases/indexing/specialized">Hash index、GIN、GiST、BRIN</a></li><li><a href="./databases/indexing/inverted-index">倒排索引与全文检索: Lucene / BM25 / Elasticsearch</a></li><li><a href="./databases/indexing/explain">执行计划：explain analyze 怎么读</a></li></ul></li><li><a href="./databases/recovery/">日志与崩溃恢复</a><ul><li><a href="./databases/recovery/aries">WAL 协议、ARIES</a></li><li><a href="./databases/recovery/checkpoint">Checkpoint、Point-in-time 恢复</a></li></ul></li><li><a href="./databases/optimization/">查询优化</a><ul><li><a href="./databases/optimization/rbo-cbo">基于规则 / 基于代价优化</a></li><li><a href="./databases/optimization/join">Join 顺序、hash join vs nested loop</a></li><li><a href="./databases/optimization/vectorized">向量化执行、列存</a></li></ul></li><li><a href="./databases/olap/">OLAP 与现代数据栈</a><ul><li><a href="./databases/olap/columnar">ClickHouse / DuckDB / Snowflake 设计</a></li><li><a href="./databases/olap/materialized">预聚合、物化视图、Cubes</a></li><li><a href="./databases/olap/lakehouse">Lakehouse：Iceberg / Delta / Hudi</a></li></ul></li></ul><hr><h1 id="第五部分-·-编译原理" tabindex="-1">第五部分 · 编译原理 <a class="header-anchor" href="#第五部分-·-编译原理" aria-label="Permalink to &quot;第五部分 · 编译原理&quot;">​</a></h1><ul><li><a href="./compilers/">开篇：编译器是软件里最挑战的工程</a></li><li><a href="./compilers/lexer/">词法分析</a><ul><li><a href="./compilers/lexer/dfa">正则 → NFA → DFA / 表驱动词法</a></li><li><a href="./compilers/lexer/unicode">Unicode、字符集、错误恢复</a></li></ul></li><li><a href="./compilers/parser/">语法分析</a><ul><li><a href="./compilers/parser/recursive-descent">递归下降 / Pratt / 错误恢复</a></li><li><a href="./compilers/parser/lr">LR/LALR/SLR/yacc/bison</a></li><li><a href="./compilers/parser/glr-peg">GLR、PEG、packrat</a></li></ul></li><li><a href="./compilers/sema/">语义分析与中间表示</a><ul><li><a href="./compilers/sema/type-system">类型系统、类型推断、HM 类型系</a></li><li><a href="./compilers/sema/ssa">SSA / CFG /支配树 / dom tree</a></li></ul></li><li><a href="./compilers/opt/">优化</a><ul><li><a href="./compilers/opt/basic">常量折叠、复写传播、死代码消除</a></li><li><a href="./compilers/opt/loop">循环优化、向量化、strength reduction</a></li><li><a href="./compilers/opt/inline">Inline / IPA / escape analysis</a></li></ul></li><li><a href="./compilers/codegen/">后端：codegen 与机器模型</a><ul><li><a href="./compilers/codegen/regalloc">寄存器分配：线性扫描 vs graph coloring</a></li><li><a href="./compilers/codegen/llvm">LLVM / cranelift 设计</a></li><li><a href="./compilers/codegen/jit">JIT / tiered compilation / V8 / JVM</a></li></ul></li></ul><hr><h1 id="第六部分-·-分布式系统" tabindex="-1">第六部分 · 分布式系统 <a class="header-anchor" href="#第六部分-·-分布式系统" aria-label="Permalink to &quot;第六部分 · 分布式系统&quot;">​</a></h1><ul><li><a href="./distributed/">开篇：分布式 = 让 N 台机器表现得像 1 台</a></li><li><a href="./distributed/concepts/">基础概念</a><ul><li><a href="./distributed/concepts/cap">CAP / PACELC / BASE</a></li><li><a href="./distributed/concepts/ordering">一致性、线性化与序</a></li><li><a href="./distributed/concepts/failure">故障检测、failure models</a></li></ul></li><li><a href="./distributed/consensus/">共识</a><ul><li><a href="./distributed/consensus/paxos">Paxos / Multi-Paxos</a></li><li><a href="./distributed/consensus/raft">Raft 详解</a></li><li><a href="./distributed/consensus/linearizability">ZooKeeper / etcd / Linearizability</a></li></ul></li><li><a href="./distributed/replication/">复制</a><ul><li><a href="./distributed/replication/topologies">主从 / 多主 / 无主复制</a></li><li><a href="./distributed/replication/crdt">CRDT：无冲突数据类型</a></li><li><a href="./distributed/replication/repair">读修复 / 反熵 / hinted handoff</a></li></ul></li><li><a href="./distributed/transactions">分布式事务: 2PC / Saga / TCC / Outbox / Spanner</a></li><li><a href="./distributed/clock/">时钟与顺序</a><ul><li><a href="./distributed/clock/logical">逻辑时钟、向量时钟、HLC</a></li><li><a href="./distributed/clock/physical">TrueTime / HLC / attestation</a></li><li><a href="./distributed/clock/dag">DAG、git、blockchain 的序</a></li></ul></li><li><a href="./distributed/fault/">分布式存储与容错</a><ul><li><a href="./distributed/fault/quorum">Quorum / W+R&gt;N / Read Repair</a></li><li><a href="./distributed/fault/erasure">Erasure coding / Reed-Solomon</a></li><li><a href="./distributed/fault/scheduling">Borg / Kubernetes / Mesos 调度</a></li></ul></li></ul><hr><h1 id="第七部分-·-系统设计" tabindex="-1">第七部分 · 系统设计 <a class="header-anchor" href="#第七部分-·-系统设计" aria-label="Permalink to &quot;第七部分 · 系统设计&quot;">​</a></h1><ul><li><a href="./system-design/">开篇：系统设计的不是&quot;答案&quot;，是&quot;分解&quot;</a></li><li><a href="./system-design/estimation/">估算与负载分析</a><ul><li><a href="./system-design/estimation/back-of-envelope">Back-of-envelope：QPS / 带宽 / 存储 / IOPS</a></li><li><a href="./system-design/estimation/littles-law">Little&#39;s Law、利用率模型</a></li><li><a href="./system-design/estimation/load-patterns">真实负载来源：幂律、长尾、突发</a></li></ul></li><li><a href="./system-design/storage/">存储选型</a><ul><li><a href="./system-design/storage/which-store">KV / 文档 / 关系 / 时序 / 向量 库选择树</a></li><li><a href="./system-design/storage/sharding">分片、分区、热点重分布</a></li><li><a href="./system-design/storage/wal-lsm-btree">WAL / LSM / B+ 三类存储层的取舍</a></li></ul></li><li><a href="./system-design/cache/">缓存设计</a><ul><li><a href="./system-design/cache/patterns">Cache-aside / Read-through / Write-through</a></li><li><a href="./system-design/cache/failure-modes">穿透 / 击穿 / 雪崩 与解决方案</a></li><li><a href="./system-design/cache/multilevel">多级缓存 / Caffeine / Nginx cache</a></li></ul></li><li><a href="./system-design/queue/">消息队列与异步</a><ul><li><a href="./system-design/queue/kafka">Kafka / Pulsar / RocketMQ 设计</a></li><li><a href="./system-design/queue/semantics">At-least-once / exactly-once / at-most-once</a></li><li><a href="./system-design/queue/outbox">Outbox pattern / Transactional Outbox</a></li></ul></li><li><a href="./system-design/scale/">扩容与高可用</a><ul><li><a href="./system-design/scale/sharding-replication">分片 / 复制 / partition tolerance</a></li><li><a href="./system-design/scale/resilience">限流 / 熔断 / 降级 / 隔离舱</a></li><li><a href="./system-design/scale/multi-region">Multi-region / Active-Active 设计</a></li></ul></li><li><a href="./system-design/monitor/">可观测性</a><ul><li><a href="./system-design/monitor/pillars">Metrics / Logs / Traces 三位一体</a></li><li><a href="./system-design/monitor/stack">Prometheus / OpenTelemetry / eBPF</a></li><li><a href="./system-design/monitor/slo">SLO / SLI / Error Budget</a></li></ul></li><li><a href="./system-design/case/">经典架构案例</a><ul><li><a href="./system-design/case/snowflake">Twitter Snowflake</a></li><li><a href="./system-design/case/google-trio">Google MapReduce / BigTable / GFS</a></li><li><a href="./system-design/case/dynamo-family">Dynamo / Cassandra / Redis Cluster</a></li><li><a href="./system-design/case/k8s-control-plane">Kubernetes 控制平面</a></li></ul></li></ul><hr><h1 id="第八部分-·-计算机组成原理" tabindex="-1">第八部分 · 计算机组成原理 <a class="header-anchor" href="#第八部分-·-计算机组成原理" aria-label="Permalink to &quot;第八部分 · 计算机组成原理&quot;">​</a></h1><ul><li><a href="./computer-arch/">开篇：从晶体管到云，硬件如何塑造软件</a></li><li><a href="./computer-arch/cpu-pipeline">CPU 流水线与指令级并行</a></li><li><a href="./computer-arch/cpu-superscalar">超标量 / OoO / Tomasulo</a></li><li><a href="./computer-arch/memory-hierarchy">存储层次：Cache / DRAM / HBM</a></li><li><a href="./computer-arch/mmu-dma">MMU / TLB / DMA / IOMMU</a></li><li><a href="./computer-arch/gpu-architecture">GPU 架构：SM / CUDA Core / Tensor Core</a></li><li><a href="./computer-arch/ai-accelerators">AI 加速器：TPU / NPU / FPGA</a></li><li><a href="./computer-arch/interconnects">总线与互联：PCIe / CXL / NVLink / RDMA</a></li><li><a href="./computer-arch/ssd-storage">存储硬件: NAND Flash / SSD FTL / 写入放大 / NVMe</a></li><li><a href="./computer-arch/isa-design">指令集架构：x86 / ARM / RISC-V</a></li></ul><hr><h1 id="第九部分-·-计算理论-formal-languages-automata-complexity" tabindex="-1">第九部分 · 计算理论（Formal Languages / Automata / Complexity） <a class="header-anchor" href="#第九部分-·-计算理论-formal-languages-automata-complexity" aria-label="Permalink to &quot;第九部分 · 计算理论（Formal Languages / Automata / Complexity）&quot;">​</a></h1><blockquote><p>把&quot;可计算&quot;形式化为 DFA / PDA / TM / 图灵机，并封顶&quot;可高效计算&quot;为 P/NP/PSPACE 等复杂度类。</p></blockquote><ul><li><a href="./theory/">开篇：从正则到不可判定，计算的四级爬升</a></li><li><a href="./theory/automata">1. 自动机：DFA → NFA → ε-NFA → 子集构造 → DFA 最小化</a></li><li><a href="./theory/regular">2. 正则语言与泵引理</a></li><li><a href="./theory/cfg-pda">3. 下推自动机（PDA）与上下文无关文法（CFG）</a></li><li><a href="./theory/turing-machine">4. 图灵机：deterministic / non-deterministic / Church-Turing</a></li><li><a href="./theory/undecidability">5. 不可判定性：停机问题、Rice 定理</a></li><li><a href="./theory/complexity">6. Complexity classes：P / NP / NPC / co-NP / PSPACE</a></li><li><a href="./theory/reductions">7. Polynomial-time reduction：3-SAT → Clique → Vertex Cover</a></li><li><a href="./theory/approximation">8. Approximation algorithms、hardness of approximation</a></li><li><a href="./theory/appendix">附录：常见判定问题分类速查表</a></li></ul><hr><h1 id="第十部分-·-密码学与安全" tabindex="-1">第十部分 · 密码学与安全 <a class="header-anchor" href="#第十部分-·-密码学与安全" aria-label="Permalink to &quot;第十部分 · 密码学与安全&quot;">​</a></h1><blockquote><p>把对抗 NPC 难度的难度转移为协议设计目标：AES / RSA / ECDHE / TLS 1.3 / ZKP 全栈。</p></blockquote><ul><li><a href="./crypto/">开篇：从凯撒密码到 TLS 1.3</a></li><li><a href="./crypto/symmetric">1. 对称加密: AES 与 ChaCha20</a></li><li><a href="./crypto/modes">2. 操作模式: ECB / CBC / CTR / GCM (AEAD) 与 nonce-reuse 灾难</a></li><li><a href="./crypto/asymmetric">3. 非对称加密: RSA 与 ECC</a></li><li><a href="./crypto/key-exchange">4. 密钥交换: DH / ECDHE / X25519</a></li><li><a href="./crypto/signatures">5. 数字签名: RSA-PSS / ECDSA / Ed25519</a></li><li><a href="./crypto/hashes">6. 哈希: SHA-256 / SHA-3 / BLAKE3 / 抗碰撞史</a></li><li><a href="./crypto/tls13">7. TLS 1.3 握手全流程</a></li><li><a href="./crypto/pki">8. 证书链: X.509 / PKI / Certificate Transparency / OCSP</a></li><li><a href="./crypto/zkp">9. ZKP 入门: zk-SNARKs / zk-STARKs / Bulletproofs</a></li><li><a href="./crypto/sidechannel">10. 侧信道攻击: timing / power analysis / Spectre / Meltdown</a></li><li><a href="./crypto/best-practices">11. 安全最佳实践: constant-time / nonce 不重用 / 密钥轮转</a></li><li><a href="./crypto/appendix">附录: 密码学考试 / 工程 checklist</a></li></ul><hr><h1 id="第十一部分-·-信息论与编码" tabindex="-1">第十一部分 · 信息论与编码 <a class="header-anchor" href="#第十一部分-·-信息论与编码" aria-label="Permalink to &quot;第十一部分 · 信息论与编码&quot;">​</a></h1><blockquote><p>Shannon 1948 一锤定音：信息熵设压缩下界、信道容量设通信上界、纠错码逼近两者之间。</p></blockquote><ul><li><a href="./info-theory/">开篇：从 Shannon 1948 到 5G NR 编解码设计</a></li><li><a href="./info-theory/entropy">1. Shannon Entropy: 离散源熵 / 联合熵 / 条件熵 / 互信息</a></li><li><a href="./info-theory/capacity">2. 信道容量: 香农公式 C = B · log₂(1 + SNR)</a></li><li><a href="./info-theory/compression">3. 无损压缩: 哈夫曼 / LZ77 / LZ78 / zstd / 算术编码 / ANS</a></li><li><a href="./info-theory/hamming">4. 汉明码: 可纠 1-bit 错误的鼻祖</a></li><li><a href="./info-theory/reed-solomon">5. Reed-Solomon 在 GF(2⁸) 上的纠错码</a></li><li><a href="./info-theory/bch">6. BCH 码、循环码与多项式基础</a></li><li><a href="./info-theory/ldpc">7. LDPC 码: 5G NR 数据信道与 Tanner 图</a></li><li><a href="./info-theory/polar">8. Polar 码: Arikan 2008 构造与 5G NR 控制信道</a></li><li><a href="./info-theory/turbo">9. Turbo 码: 3G/4G 并行级联卷积码与 BCJR 迭代</a></li><li><a href="./info-theory/modulation">10. 调制: QPSK / 16-QAM / 64-QAM 星座图与误码率</a></li><li><a href="./info-theory/appendix">附录: 编码率 / 纠错能力 / SNR 实践速查</a></li></ul><hr><h1 id="第十二部分-·-人工智能与机器学习" tabindex="-1">第十二部分 · 人工智能与机器学习 <a class="header-anchor" href="#第十二部分-·-人工智能与机器学习" aria-label="Permalink to &quot;第十二部分 · 人工智能与机器学习&quot;">​</a></h1><blockquote><p>把分散在第零部分数学、第八部分 GPU/AI 加速器、第十一部分信息论 KL/熵的&quot;积木&quot;，在 ML 这一处集大成。数学预备已在第零部分就位，本部分直接引用。</p></blockquote><ul><li><a href="./ai-ml/">开篇：从线性回归到 Transformer 的 70 年</a></li><li><a href="./ai-ml/foundations">1. Foundations: 线性回归 → 逻辑回归 → MLP → 损失函数谱 → 泛化与正则</a></li><li><a href="./ai-ml/backprop">2. Backpropagation: 计算图 / 反向模式 AD / 雅可比链式 / 梯度检查</a></li><li><a href="./ai-ml/transformer">3. Transformer: self-attention / MHA / FFN / LayerNorm / 残差 / Encoder-Decoder / 训练损失</a></li><li><a href="./ai-ml/optimizers">4. Optimizers &amp; Training Dynamics: Adam/AdamW/二阶 + 初始化/LayerNorm/warmup/checkpoint</a></li><li><a href="./ai-ml/generative">5. Generative Models: VAE &amp; ELBO / 扩散模型 / AR 采样 / speculative decoding</a></li><li><a href="./ai-ml/classical-ml">6. 经典机器学习与树模型: 决策树 / GBDT / XGBoost / SVM</a></li><li><a href="./ai-ml/tokenizer">7. Tokenizer 与 Embedding: BPE / WordPiece / SentencePiece / 位置编码</a></li><li><a href="./ai-ml/rl">8. 强化学习与 RLHF: MDP / Bellman / Q-learning / Policy Gradient / PPO / RLHF</a></li><li><a href="./ai-ml/training-at-scale">9. 大模型训练工程: DP/PP/TP/ZeRO/FSDP/Checkpoint</a></li><li><a href="./ai-ml/contrastive-learning">10. 表示学习与对比学习: SimCLR / CLIP / InfoNCE</a></li><li><a href="./ai-ml/agents">11. LLM Agent: Tool Use / ReAct / Plan-Execute / Multi-Agent / Memory</a></li><li><a href="./ai-ml/multimodal">12. 多模态: 跨注意力 / Flamingo / LLaVA / BLIP-2 / 扩散多模态</a></li><li><a href="./ai-ml/llm-inference">13. LLM 推理与部署: KV Cache / PagedAttention / 连续批处理 / 量化</a></li></ul><hr><h1 id="第十三部分-·-元抽象-跨章节大主题" tabindex="-1">第十三部分 · 元抽象：跨章节大主题 <a class="header-anchor" href="#第十三部分-·-元抽象-跨章节大主题" aria-label="Permalink to &quot;第十三部分 · 元抽象：跨章节大主题&quot;">​</a></h1><blockquote><p>把前面十二部分反复出现的概念，往上一层抽出来做横向对比。每篇都假设你已经读完前面的具体章节。</p></blockquote><ul><li><a href="./_meta/">开篇：为什么要再抽一层</a></li><li><a href="./_meta/contiguous-vs-linked">1. 顺序 vs 链接：CPU 视角下两种物理化</a></li><li><a href="./_meta/amortized-vs-worst">2. 摊还 vs 最坏：工程常数与硬实时的张力</a></li><li><a href="./_meta/decomposition-strategies">3. 分治 vs 贪心 vs DP：什么是&quot;最优子问题分解&quot;</a></li><li><a href="./_meta/memory-hierarchy">4. 缓存层级：从 L1 到 HBM 到 RDMA 的同构</a></li><li><a href="./_meta/runtime-semantics">5. 编程语言运行时：四种实现语义</a></li><li><a href="./_meta/concurrency-consistency">6. 并发与一致性：单机到分布式同构</a></li><li><a href="./_meta/hardware-shapes-software">7. 推理链：硬件层如何决定软件设计</a></li></ul><hr><h1 id="形式化方法卷-·-用数学证明-系统是对的" tabindex="-1">形式化方法卷 · 用数学证明&quot;系统是对的&quot; <a class="header-anchor" href="#形式化方法卷-·-用数学证明-系统是对的" aria-label="Permalink to &quot;形式化方法卷 · 用数学证明&quot;系统是对的&quot;&quot;">​</a></h1><blockquote><p>测试能证明有 bug, 但永远不能证明没 bug。模型检查穷举状态空间, 定理证明验证数学证明, 程序验证把证明连到真实代码——Raft 有 TLA+、CompCert 用 Coq、seL4 被 Isabelle 证明。</p></blockquote><ul><li><a href="./formal/">开篇: 用数学证明&quot;系统是对的&quot;</a><ul><li><a href="./formal/model-checking-tla">1. 模型检查与 TLA+: 穷举状态空间找反例</a></li><li><a href="./formal/coq-lean">2. 定理证明: Coq / Lean / 依赖类型 / Curry-Howard</a></li><li><a href="./formal/program-verification">3. 程序验证: Hoare 逻辑 / 符号执行 / 形式语义</a></li></ul></li></ul><hr><h1 id="量子计算卷-·-用量子比特重新定义-计算" tabindex="-1">量子计算卷 · 用量子比特重新定义&quot;计算&quot; <a class="header-anchor" href="#量子计算卷-·-用量子比特重新定义-计算" aria-label="Permalink to &quot;量子计算卷 · 用量子比特重新定义&quot;计算&quot;&quot;">​</a></h1><blockquote><p>量子比特叠加 + 纠缠带来对特定问题的指数/平方加速。基础 (Dirac 记号 / 门 / 测量) → 算法 (Deutsch-Jozsa / Grover / Shor) → 纠错 (surface code / 逻辑 qubit) 一路讲透, 并给出现实的 Y2Q 判断。</p></blockquote><ul><li><a href="./quantum/">开篇: 用量子比特重新定义&quot;计算&quot;</a><ul><li><a href="./quantum/basics">1. 量子计算基础: Dirac 记号 / qubit / 量子门 / 测量</a></li><li><a href="./quantum/algorithms">2. 量子算法: Deutsch-Jozsa / Grover / Shor</a></li><li><a href="./quantum/error-correction">3. 量子纠错: 逻辑 qubit / surface code / 现实挑战</a></li></ul></li></ul><hr><p><a href="./TODO">TODO / 待补充模块</a></p>',72)])])}const m=e(t,[["render",o]]);export{d as __pageData,m as default};
